import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"Depot-Related Priority Phenomena","description":"","frontmatter":{"translationSource":{"title":"仓库相关优先级现象","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pgnaI2HtL8UdrJqoloJQvA","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/depot-related-priority-phenomena"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/depot-related-priority-phenomena"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/depot-related-priority-phenomena"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/depot-related-priority-phenomena"}]]},"headers":[],"relativePath":"depot-related-priority-phenomena.md","filePath":"logistics/src/page-pgnaI2HtL8UdrJqoloJQvA.md"}'),i={name:"depot-related-priority-phenomena.md"};function n(d,e,l,p,s,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><h1 id="depot-related-priority-phenomena" tabindex="-1">Depot-Related Priority Phenomena <a class="header-anchor" href="#depot-related-priority-phenomena" aria-label="Permalink to &quot;Depot-Related Priority Phenomena&quot;">​</a></h1><blockquote><p>Source page ID: <code>pgnaI2HtL8UdrJqoloJQvA</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=pgnaI2HtL8UdrJqoloJQvA" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-d5922f12e457a433.q90-04b897c52e14153c.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-fd14ff7c64c73e3f.q90-e2565d9429a53c5e.webp" alt="Image"></td></tr></tbody></table><p>In this structure, placing the two Depot Unloaders A and B again, together with the belt connected to A, gives A priority.</p><p>Replacing a Depot Loader alone may put it into a low-priority state, but this cannot be achieved reliably; the outcome and required number of attempts are uncertain — in other words, the priority problem essentially appears at random.</p><p>Tests show that this phenomenon (Unloader priority) is almost always corrected after logging out, and it can usually be ignored. However, that conclusion cannot be made reliable; sometimes logging out even triggers the problem instead.</p><p>It is uncertain whether Reactor Crucibles exhibit a similar phenomenon (Unloader priority).</p><p>Depot Loaders exhibit the same input-priority phenomenon as Reactor Crucibles: first connected, first input.</p><p>In addition, the Protocol Automation-Core (PAC) exhibits the same phenomena (Unloader priority and Loader priority), and this behavior may be stable.</p></div>',1)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
